import os
from typing import Any, Dict, Iterable, List, Optional, Tuple

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _get_thresholds() -> Dict[str, float]:
    thresholds_raw = os.getenv("PERSPECTIVE_CATEGORY_THRESHOLDS", "")
    thresholds: Dict[str, float] = {}
    for item in thresholds_raw.split(","):
        item = item.strip()
        if not item or "=" not in item:
            continue
        key, value = item.split("=", 1)
        key = key.strip().upper()
        try:
            thresholds[key] = float(value.strip())
        except ValueError:
            continue
    return thresholds


def _default_thresholds() -> Dict[str, float]:
    return {
        "TOXICITY": 0.80,
        "SEVERE_TOXICITY": 0.70,
        "IDENTITY_ATTACK": 0.75,
        "INSULT": 0.80,
        "PROFANITY": 0.85,
        "THREAT": 0.50,
        "SEXUALLY_EXPLICIT": 0.70,
        "FLIRTATION": 0.90,
    }


def _merge_thresholds() -> Dict[str, float]:
    thresholds = _default_thresholds()
    thresholds.update(_get_thresholds())
    return thresholds


def _build_request_payload(text: str, languages: Optional[List[str]] = None) -> Dict[str, Any]:
    requested_attributes = {name: {} for name in _default_thresholds().keys()}
    payload: Dict[str, Any] = {
        "comment": {"text": text},
        "requestedAttributes": requested_attributes,
        "spanAnnotations": False,
    }
    if languages:
        payload["languages"] = languages
    return payload


def _extract_scores(response_json: Dict[str, Any]) -> Dict[str, float]:
    scores: Dict[str, float] = {}
    attr_scores = response_json.get("attributeScores", {})
    for category, data in attr_scores.items():
        score = (
            data.get("summaryScore", {})
            .get("value")
        )
        if isinstance(score, (int, float)):
            scores[category.upper()] = float(score)
    return scores


def _decision_from_scores(scores: Dict[str, float], thresholds: Dict[str, float]) -> Tuple[bool, Dict[str, Any]]:
    violations: List[Dict[str, Any]] = []
    for category, threshold in thresholds.items():
        score = scores.get(category)
        if score is None:
            continue
        if score >= threshold:
            violations.append(
                {
                    "category": category,
                    "score": score,
                    "threshold": threshold,
                }
            )
    allow = len(violations) == 0
    return allow, {"violations": violations, "scores": scores}


def evaluate_text_safety(text: str, languages: Optional[List[str]] = None, timeout: float = 10.0) -> Dict[str, Any]:
    api_key = os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ValueError("PERSPECTIVE_API_KEY is not set")

    thresholds = _merge_thresholds()
    payload = _build_request_payload(text, languages=languages)

    params = {"key": api_key}
    headers = {"Content-Type": "application/json"}

    resp = requests.post(
        PERSPECTIVE_API_URL,
        params=params,
        headers=headers,
        json=payload,
        timeout=timeout,
    )
    resp.raise_for_status()
    response_json = resp.json()

    scores = _extract_scores(response_json)
    allow, details = _decision_from_scores(scores, thresholds)

    result = {
        "allow": allow,
        "text": text,
        "thresholds": thresholds,
        **details,
        "raw": response_json,
    }
    return result


def allow_text(text: str, languages: Optional[List[str]] = None) -> bool:
    return bool(evaluate_text_safety(text, languages=languages)["allow"])
